        return 1
    ref = (args.ref or "").strip()
    if args.action == "addon":
        _, msg, err = addon(root, args.name, args.text, args.why or "", ref, args.replace)
    elif err := _ref_error(root, ref, required=True):
        msg = ""
    else:
        _, msg, err = sync(root, args.file, args.why or "", ref)
